export const AREA_CLASSES = ["art:text-blue-500", "art:text-teal-500", "art:text-orange-500", "art:text-amber-500", "art:text-sky-500", "art:text-rose-500"];
export function unlockedFraction(a: Allocation, month: number): number {
    if (month <= a.cliff || a.linear === 0)
        return month <= a.cliff ? a.launch : 1;
    return Math.min(1, a.launch + ((1 - a.launch) * (month - a.cliff)) / a.linear);
