        {ALLOCATIONS.map((a, i) => (<Area key={a.name} type="linear" dataKey={AREA_KEYS[i]} name={a.name} stackId="unlock" stroke="var(--artemis-background)" strokeWidth={1.5} fill="currentColor" fillOpacity={0.9} activeDot={false} className={artemisCx(AREA_CLASSES[i], "art:transition-opacity art:duration-200", active !== null && active !== i && "art:opacity-20")}/>))}
        <ReferenceLine x={CLIFF_MONTH} stroke="var(--artemis-muted-foreground)" strokeDasharray="3 4" strokeOpacity={0.6} label={{ value: "Cliffs end", position: "insideTopLeft", fontSize: 11, fill: "var(--artemis-muted-foreground)", offset: 8 }}/>
        {hoverMonth !== null ? <ReferenceLine x={hoverMonth} stroke="var(--artemis-foreground)" strokeOpacity={0.5}/> : null}
      </AreaChart>
    </ResponsiveContainer>);
}
